// Shared visual-only Work Order print branding. The embedded existing letterhead
// keeps browser, offline printing and automatic email PDFs independent of image fetches.
(function (root) {
  "use strict";
  root.JgcWorkOrderPdfBranding = Object.freeze({
    css: `  @page { size: letter; margin: 0.5in; }
  * { box-sizing: border-box; }
  body { font-family: Arial, Helvetica, sans-serif; color: #202e29; background: #fff; margin: 0; font-size: 12px; line-height: 1.45; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .pdf-header { display: table; width: 100%; border-bottom: 2px solid #245c49; padding-bottom: 12px; margin-bottom: 16px; break-inside: avoid; }
  .brand { display: table-cell; width: 65%; vertical-align: middle; font-size: 8px; font-weight: bold; color: #52645b; letter-spacing: 1px; }
  .brand img { display: block; width: 238px; height: auto; margin-bottom: 7px; }
  h1 { display: table-cell; vertical-align: middle; text-align: right; font-size: 27px; line-height: 1.15; font-weight: bold; color: #245c49; margin: 0; }
  h2 { color: #245c49; font-size: 14px; line-height: 1.3; border-bottom: 1px solid #c3d3cc; padding-bottom: 6px; margin: 20px 0 8px; break-after: avoid; page-break-after: avoid; }
  .summary { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); border: 1px solid #cbd5cf; background: #f6f8f7; break-inside: avoid; }
  .summary div { border-bottom: 1px solid #dce3df; padding: 8px 10px; min-height: 48px; overflow-wrap: anywhere; }
  .summary div:nth-child(odd) { border-right: 1px solid #dce3df; }
  .summary div:nth-last-child(-n+2) { border-bottom: 0; }
  .summary b { display: block; font-size: 9px; font-weight: bold; text-transform: uppercase; letter-spacing: .5px; color: #52645b; margin-bottom: 3px; }
  table { width: 100%; table-layout: fixed; border-collapse: collapse; margin-top: 8px; font-size: 11px; line-height: 1.4; page-break-inside: auto; }
  thead { display: table-header-group; }
  tr { break-inside: avoid; page-break-inside: avoid; }
  th, td { border: 1px solid #d2dcd6; padding: 7px 8px; vertical-align: top; overflow-wrap: anywhere; }
  th { background: #edf3ef; color: #245c49; font-size: 10px; font-weight: bold; text-align: left; }
  tbody tr:nth-child(even) { background: #fafbfa; }
  .labour-table th:last-child, .labour-table td:last-child { width: 100px; text-align: right; font-variant-numeric: tabular-nums; }
  .labour-table td.empty { text-align: left; width: auto; }
  .pdf-table--7 th:nth-child(1) { width: 20%; }
  .pdf-table--7 th:nth-child(2) { width: 12%; }
  .pdf-table--7 th:nth-child(3) { width: 16%; }
  .pdf-table--7 th:nth-child(4) { width: 9%; }
  .pdf-table--7 th:nth-child(5), .pdf-table--7 th:nth-child(6) { width: 8%; }
  .pdf-table--7 th:nth-child(7) { width: 27%; }
  .description { border: 1px solid #d2dcd6; min-height: 65px; padding: 10px; white-space: pre-wrap; overflow-wrap: anywhere; }
  .empty { color: #52645b; font-style: italic; }
  .totals { font-weight: bold; background: #edf3ef !important; }
  .signatures { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 32px; margin-top: 26px; padding-top: 40px; break-inside: avoid; page-break-inside: avoid; }
  .line { border-top: 1px solid #64796c; padding-top: 7px; color: #52645b; font-size: 10px; }
`,
    logo: "data:image/jpeg;base64,"
  });
})(globalThis);
